style.css:
@-moz-document domain("google.com") {
/* Selecciona el logo principal */
    img.lnXdpd {
        filter: brightness(0) invert(1);   /* Lo vuelve blanco */
        image-rendering: pixelated;        /* Efecto pixel */
        image-rendering: crisp-edges;      /* Más pixel */
        transform: scale(1.05);            /* Opcional: leve aumento */
    }

    /* Si Google usa el logo en SVG */
    svg[aria-label="Google"] {
        filter: brightness(0) invert(1);
        image-rendering: pixelated;
    }
}
